function db(): PDO {
    static $db;
    if ($db) return $db;
    $db = new PDO('sqlite:' . STORE . '/music.sqlite', null, null, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
    $db->exec('PRAGMA foreign_keys = ON');
    $db->exec('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');
    $db->exec('CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, artist TEXT NOT NULL, title TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ("CD","LP")), barcode TEXT, tracklist TEXT, release_year INTEGER, duration_seconds INTEGER, cover_path TEXT, back_path TEXT, barcode_path TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT, user_id INTEGER NOT NULL REFERENCES users(id))');
    try { $db->exec('ALTER TABLE records ADD COLUMN deleted_at TEXT'); } catch (Throwable $e) {}
    try { $db->exec('ALTER TABLE records ADD COLUMN release_year INTEGER'); } catch (Throwable $e) {}
    try { $db->exec('ALTER TABLE records ADD COLUMN duration_seconds INTEGER'); } catch (Throwable $e) {}
    $db->exec('CREATE INDEX IF NOT EXISTS records_barcode ON records(barcode)');
    return $db;
}
function e(?string $value): string { return htmlspecialchars($value ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function playtime(?int $seconds): string { if (!$seconds) return 'Onbekend'; return floor($seconds / 60) . ':' . str_pad((string)($seconds % 60), 2, '0', STR_PAD_LEFT); }
function loggedIn(): bool { return isset($_SESSION['user_id']); }
function requireLogin(): void { if (!loggedIn()) { header('Location: ?page=login'); exit; } }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function checkCsrf(): void { if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(403); exit('Ongeldig formulierverzoek. Vernieuw de pagina en probeer opnieuw.'); } }
function flash(string $message, string $type='ok'): void { $_SESSION['flash']=[$message,$type]; }
function redirect(string $url): void { header('Location: '.$url); exit; }
function imageUpload(string $key): ?string {
    if (empty($_FILES[$key]['tmp_name']) || $_FILES[$key]['error'] === UPLOAD_ERR_NO_FILE) return null;
    if ($_FILES[$key]['error'] !== UPLOAD_ERR_OK || $_FILES[$key]['size'] > 10 * 1024 * 1024) throw new RuntimeException('Elke foto moet kleiner zijn dan 10 MB.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$key]['tmp_name']);
    $extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if (!isset($extensions[$mime])) throw new RuntimeException('Gebruik een JPG, PNG of WebP-afbeelding.');
    $name=bin2hex(random_bytes(20)).'.'.$extensions[$mime];
    if (!move_uploaded_file($_FILES[$key]['tmp_name'], UPLOADS.'/'.$name)) throw new RuntimeException('Foto kon niet veilig opgeslagen worden.');
    return $name;
}
function outputCoverForBarcode(string $barcode): never {
    $safe=preg_replace('/[^0-9A-Za-z]/','',$barcode);
    $context=stream_context_create(['http'=>['header'=>"User-Agent: MijnMuziekCollectie/1.0 (personal collection app)\r\nAccept: application/json\r\n",'timeout'=>8,'follow_location'=>1]]);
    $raw=@file_get_contents('https://musicbrainz.org/ws/2/release?query=barcode:'.rawurlencode($safe).'&fmt=json&limit=1',false,$context);
    $data=$raw?json_decode($raw,true):null; $id=$data['releases'][0]['id']??'';
    if (!preg_match('/^[a-f0-9-]{36}$/i',$id)) { http_response_code(404); exit; }
    $url='https://coverartarchive.org/release/'.rawurlencode($id).'/front-250';
    $image=@file_get_contents($url,false,$context);
    if ($image===false) { http_response_code(404); exit; }
    foreach ($http_response_header ?? [] as $header) if (stripos($header,'Content-Type:')===0) { header($header); break; }
    header('Cache-Control: private, max-age=604800'); echo $image; exit;
}
function musicRelease(string $barcode): array {
    $safe=preg_replace('/[^0-9A-Za-z]/','',$barcode);
    $context=stream_context_create(['http'=>['header'=>"User-Agent: MijnMuziekCollectie/1.0 (personal collection app)\r\nAccept: application/json\r\n",'timeout'=>10]]);
    $raw=@file_get_contents('https://musicbrainz.org/ws/2/release?query=barcode:'.rawurlencode($safe).'&fmt=json&limit=1',false,$context);
    $search=$raw?json_decode($raw,true):null; $release=$search['releases'][0]??null; if (!$release) throw new RuntimeException('Geen albumgegevens gevonden voor deze barcode.');
    $detail=@file_get_contents('https://musicbrainz.org/ws/2/release/'.rawurlencode($release['id']).'?inc=recordings+artist-credits&fmt=json',false,$context);
    $full=$detail?json_decode($detail,true):$release; $artist=$full['artist-credit'][0]['name']??''; $title=$full['title']??'';
    if (!$artist || !$title) throw new RuntimeException('De gevonden uitgave bevat geen bruikbare artiest of titel.');
    $tracks=[];$duration=0; foreach($full['media']??[] as $medium) foreach($medium['tracks']??[] as $track) {$tracks[]=($track['number']??'').'. '.($track['title']??'');$duration+=(int)(($track['length']??0)/1000);}
    $mediumFormat=(string)($full['media'][0]['format']??''); $format=str_contains(strtolower($mediumFormat),'vinyl')?'LP':'CD';
    $year=preg_match('/^(\d{4})/',(string)($full['date']??$release['date']??''),$match)?(int)$match[1]:null;
    return ['id'=>$full['id']??$release['id'],'release_group'=>$full['release-group']['id']??$release['release-group']['id']??null,'artist'=>$artist,'title'=>$title,'format'=>$format,'year'=>$year,'duration_seconds'=>$duration?:null,'tracklist'=>implode("\n",$tracks)];
}
function downloadCover(string $releaseId, ?string $releaseGroupId=null, ?string &$error=null): ?string {
    $error=null;
    if (!preg_match('/^[a-f0-9-]{36}$/i',$releaseId)) return null;
    $urls=['https://coverartarchive.org/release/'.rawurlencode($releaseId).'/front-500'];
    if ($releaseGroupId && preg_match('/^[a-f0-9-]{36}$/i',$releaseGroupId)) $urls[]='https://coverartarchive.org/release-group/'.rawurlencode($releaseGroupId).'/front-500';
    $image=null;$type='';foreach($urls as $url){$curl=curl_init($url);curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_TIMEOUT=>20,CURLOPT_USERAGENT=>'MijnMuziekCollectie/1.0']);$candidate=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);$candidateType=(string)curl_getinfo($curl,CURLINFO_CONTENT_TYPE);curl_close($curl);if(is_string($candidate)&&$status===200&&strlen($candidate)>1000){$image=$candidate;$type=$candidateType;break;}}
    if (!is_string($image)) return null;
    $mime=explode(';',$type)[0];$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)return null;
    $dir=UPLOADS.'/covers';if(!is_dir($dir) && !mkdir($dir,0750,true) && !is_dir($dir)){$error='De hoes kon niet lokaal worden opgeslagen: de opslagmap is niet schrijfbaar.';return null;}$name='covers/'.bin2hex(random_bytes(20)).'.'.$ext;
    if(file_put_contents(UPLOADS.'/'.$name,$image,LOCK_EX)===false){$error='De hoes kon niet lokaal worden opgeslagen. Controleer schrijfrechten op storage/uploads/covers.';return null;}return $name;
}
function layout(string $title, string $content): never {
