    $nav=$logged ? '<nav><a class="'.($page==='dashboard'?'active':'').'" href="?page=dashboard">Collectie</a><a class="'.($page==='add'?'active':'').'" href="?page=add">Handmatig toevoegen</a><a class="'.($page==='scan'?'active':'').'" href="?page=scan">Scannen</a><a class="'.($page==='trash'?'active':'').'" href="?page=trash">Prullenbak</a><a class="'.($page==='integrations'?'active':'').'" href="?page=integrations">Integraties</a><a href="?action=logout">Uitloggen</a></nav>' : '';
    $nav=str_replace('</nav>','<a id="update-button" class="update-link" href="?page=updates">Updates</a></nav>',$nav);
    $content='<i id="csrf-token" data-token="'.csrf().'" hidden></i>'.$content;
    $content.='<link rel="stylesheet" href="assets/collection-list.css?v='.$assetVersion.'"><link rel="stylesheet" href="assets/scan.css?v='.$assetVersion.'"><script src="assets/update.js?v='.$assetVersion.'" defer></script><script src="assets/direct-scanner.js?v='.$assetVersion.'" defer></script>';
    $notice=$flash ? '<div class="notice '.($flash[1]==='error'?'error':'').'">'.e($flash[0]).'</div>' : '';
    echo '<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#e8466d"><title>'.e($title).' · Mijn Muziek</title><link rel="stylesheet" href="assets/app.css?v='.$assetVersion.'"></head><body><main class="shell"><header class="topbar"><a class="brand" href="?page=dashboard">mijn<span>muziek</span></a>'.$nav.'</header>'.$notice.$content.'</main><script src="assets/app.js?v='.$assetVersion.'" defer></script></body></html>'; exit;
}

