if (($_GET['action'] ?? '') === 'vision-barcode') { requireLogin(); header('Content-Type: application/json'); checkCsrf(); try { if (empty($_FILES['barcode_photo']['tmp_name']) || $_FILES['barcode_photo']['error'] !== UPLOAD_ERR_OK || $_FILES['barcode_photo']['size'] > 10 * 1024 * 1024) throw new RuntimeException('Maak eerst een barcodefoto van maximaal 10 MB.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['barcode_photo']['tmp_name']); $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null; if (!$ext) throw new RuntimeException('Gebruik een JPG, PNG of WebP-foto.'); $dir=UPLOADS.'/scans'; if (!is_dir($dir)) mkdir($dir,0750,true); $name='scans/'.bin2hex(random_bytes(20)).'.'.$ext; if (!move_uploaded_file($_FILES['barcode_photo']['tmp_name'],UPLOADS.'/'.$name)) throw new RuntimeException('Barcodefoto kon niet veilig worden opgeslagen.'); echo json_encode(['barcode' => VisionBarcode::read(UPLOADS.'/'.$name), 'scan_photo' => $name]); } catch (Throwable $e) { http_response_code(422); echo json_encode(['error' => $e->getMessage()]); } exit; }
if (($_GET['action'] ?? '') === 'lookup') { requireLogin(); header('Content-Type: application/json'); $barcode=preg_replace('/[^0-9A-Za-z]/','',$_GET['barcode']??''); if (strlen($barcode)<6) { http_response_code(422); echo json_encode(['error'=>'Ongeldige barcode.']); exit; }
    $url='https://musicbrainz.org/ws/2/release?query=barcode:'.rawurlencode($barcode).'&fmt=json&limit=1';
