    $raw=@file_get_contents($url,false,$context); $data=$raw?json_decode($raw,true):null; $release=$data['releases'][0]??null;
    if(!$release){http_response_code(404);echo json_encode(['error'=>'Geen uitgave gevonden in MusicBrainz.']);exit;}
    $detail=@file_get_contents('https://musicbrainz.org/ws/2/release/'.rawurlencode($release['id']).'?inc=recordings+artist-credits&fmt=json',false,$context); $full=$detail?json_decode($detail,true):$release;
    $tracks=[]; foreach($full['media']??[] as $medium) foreach($medium['tracks']??[] as $track) $tracks[]=($track['number']??'').'. '.($track['title']??'');
    $mediumFormat=(string)($full['media'][0]['format']??''); $normalized=strtolower($mediumFormat); $collectionFormat=str_contains($normalized,'vinyl')?'LP':((in_array($normalized,['cd','compact disc'],true) || str_contains($normalized,'compact disc'))?'CD':'');
    echo json_encode(['release'=>['title'=>$full['title']??'', 'artist'=>$full['artist-credit'][0]['name']??'', 'format'=>$mediumFormat, 'collectionFormat'=>$collectionFormat, 'tracks'=>implode("\n",$tracks)]]); exit;
}
if (($_GET['action'] ?? '') === 'check') { requireLogin(); header('Content-Type: application/json'); $barcode=preg_replace('/\D/','',$_GET['barcode']??'');$alternate=strlen($barcode)===12?'0'.$barcode:(strlen($barcode)===13&&str_starts_with($barcode,'0')?substr($barcode,1):$barcode); $s=db()->prepare('SELECT artist,title,format FROM records WHERE barcode IN (?,?) AND user_id=? AND deleted_at IS NULL LIMIT 1'); $s->execute([$barcode,$alternate,$_SESSION['user_id']]); $r=$s->fetch();if($r){echo json_encode(['found'=>true]+$r);exit;}try{$release=musicRelease($barcode);echo json_encode(['found'=>false,'release'=>$release]);}catch(Throwable $e){echo json_encode(['found'=>false,'release'=>null]);}exit; }
if (($_GET['action'] ?? '') === 'add-from-barcode') { requireLogin(); header('Content-Type: application/json'); checkCsrf(); try { $barcode=preg_replace('/[^0-9A-Za-z]/','',$_POST['barcode']??''); if (strlen($barcode)<8) throw new RuntimeException('Ongeldige barcode.'); $existing=db()->prepare('SELECT id FROM records WHERE barcode=? AND user_id=? AND deleted_at IS NULL'); $existing->execute([$barcode,$_SESSION['user_id']]); if ($existing->fetch()) throw new RuntimeException('Deze uitgave staat al in je collectie.'); $release=musicRelease($barcode); $photo=$_POST['scan_photo']??''; if (!preg_match('#^scans/[a-f0-9]{40}\.(jpg|png|webp)$#',$photo) || !is_file(UPLOADS.'/'.$photo)) $photo=null; $coverError=null;$cover=downloadCover($release['id'],$release['release_group'],$coverError); db()->prepare('INSERT INTO records(artist,title,format,barcode,tracklist,release_year,duration_seconds,cover_path,barcode_path,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$release['artist'],$release['title'],$release['format'],$barcode,$release['tracklist'],$release['year'],$release['duration_seconds'],$cover,$photo,$_SESSION['user_id']]); echo json_encode($release+['cover_warning'=>$coverError]); } catch(Throwable $e) { http_response_code(422); echo json_encode(['error'=>$e->getMessage()]); } exit; }

$count=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();
