if($page==='add') layout('Handmatig toevoegen','<section class="hero"><h1>Handmatig toevoegen.</h1><p>Vul de gegevens zelf in. Voor automatisch scannen gebruik je het scherm Scannen.</p></section><section class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="record"><div class="form-grid"><div><label>Artiest</label><input name="artist" required></div><div><label>Titel</label><input name="title" required></div><div><label>Type</label><select name="format" required><option value="CD">CD</option><option value="LP">LP / vinyl</option></select></div><div><label>Barcode</label><input name="barcode" inputmode="numeric" placeholder="Bijv. 871..."></div><div><label>Jaar</label><input name="release_year" inputmode="numeric" min="1000" max="9999"></div><div><label>Lengte <span class="muted">(seconden)</span></label><input name="duration_seconds" inputmode="numeric" min="0"></div><div class="span-2"><label>Albumhoes uploaden</label><input type="file" name="cover" accept="image/*" capture="environment"><p class="muted">Kies een bestaande scan of maak direct een foto van de albumhoes.</p></div><div class="span-2"><label>Tracklijst</label><textarea name="tracklist" placeholder="Eén nummer per regel"></textarea></div></div><div class="actions"><button>Opslaan in collectie</button></div></form></section>');
if($page==='integrations') { $state=VisionBarcode::configured()?'Actief':'Niet ingesteld'; layout('Integraties','<section class="card auth"><h1>OpenAI Vision</h1><p>Gebruik vision-herkenning om de cijfers onder een barcode betrouwbaarder uit te lezen.</p><p><span class="tag">'.e($state).'</span></p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="openai_settings"><input type="hidden" name="mode" value="save"><label>OpenAI API-sleutel</label><input type="password" name="openai_api_key" autocomplete="new-password" placeholder="sk-..." required><p class="muted">De sleutel wordt alleen buiten de webmap opgeslagen, nooit weergegeven en nooit naar GitHub gestuurd.</p><div class="actions"><button>Integratie opslaan</button></div></form>'.(VisionBarcode::configured()?'<form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="openai_settings"><input type="hidden" name="mode" value="remove"><div class="actions"><button class="secondary" type="submit">Sleutel verwijderen</button></div></form>':'').'</section>'); }
if($page==='updates') layout('Updates','<section class="card auth"><h1>Software-update</h1><p id="update-message" class="muted">Controleren of er een nieuwe versie is…</p><p>Updates worden via HTTPS van de openbare GitHub-repository opgehaald. Je database en foto’s blijven staan; vóór installatie maakt de app een back-up in <code>storage/backups</code>.</p><div class="actions"><button id="check-updates" class="secondary" type="button">Nu controleren op updates</button></div><form id="install-update-form" method="post" hidden><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="apply_update"><div class="actions"><button id="install-update" type="submit">Update installeren</button></div></form></section>');
if($page==='scan') layout('Barcode lezen','<section class="card scan-box"><h1>Heb ik deze al?</h1><p class="muted">Maak een foto met de achtercamera; de cijfers onder de barcode worden gelezen en met je collectie vergeleken.</p><video id="scanner-video" hidden playsinline style="width:100%;border-radius:12px"></video><div class="actions" style="justify-content:center"><button id="start-scan">Open achtercamera</button></div><p id="scan-status" class="muted"></p><div id="scan-result" class="scan-result">Nog niets gecontroleerd.</div></section>');
if($page==='trash') { $s=db()->prepare('SELECT * FROM records WHERE user_id=? AND deleted_at IS NOT NULL ORDER BY deleted_at DESC');$s->execute([$_SESSION['user_id']]);$trash=$s->fetchAll();$items='';foreach($trash as $r)$items.='<article class="record"><div class="record-body"><span class="tag">'.e($r['format']).'</span><h2>'.e($r['artist']).'</h2><p>'.e($r['title']).'</p></div></article>';layout('Prullenbak','<section class="hero"><h1>Prullenbak</h1><p>Verwijderde uitgaven staan hier tot je de prullenbak leegt.</p></section>'.($items?'<section class="collection collection-list">'.$items.'</section><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="empty_trash"><div class="actions"><button>Prullenbak definitief legen</button></div></form>':'<section class="card empty">De prullenbak is leeg.</section>')); }
if($page==='record') { $s=db()->prepare('SELECT * FROM records WHERE id=? AND user_id=? AND deleted_at IS NULL');$s->execute([(int)($_GET['id']??0),$_SESSION['user_id']]);$r=$s->fetch();if(!$r){http_response_code(404);layout('Niet gevonden','<p>Deze uitgave bestaat niet.</p>');}$cover=($r['cover_path']||$r['barcode'])?'<img src="?action=image&id='.$r['id'].'" alt="Voorkant van '.e($r['title']).'">':'<div class="cover"></div>';$year=$r['release_year']?(string)$r['release_year']:'Onbekend';$added=date('d-m-Y',strtotime($r['created_at']));layout($r['title'],'<section class="details"><div>'.$cover.'</div><div><span class="tag">'.e($r['format']).'</span><h1>'.e($r['artist']).'<br>'.e($r['title']).'</h1><p class="muted">Jaar: '.e($year).' · Lengte: '.e(playtime($r['duration_seconds']?(int)$r['duration_seconds']:null)).'<br>Toegevoegd op: '.e($added).'</p>'.($r['barcode']?'<p class="muted">Barcode: '.e($r['barcode']).'</p>':'').'<h2>Tracklijst</h2><p class="tracklist">'.(e($r['tracklist'])?:'Niet vastgelegd.').'</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="delete_record"><input type="hidden" name="id" value="'.$r['id'].'"><div class="actions"><button class="secondary" type="submit">Album verwijderen</button></div></form></div></section>'); }
$statement=db()->prepare('SELECT * FROM records WHERE user_id=? AND deleted_at IS NULL ORDER BY created_at DESC');$statement->execute([$_SESSION['user_id']]);$rows=$statement->fetchAll();$items='';foreach($rows as $r){$image=($r['cover_path']||$r['barcode'])?'<img class="cover" src="?action=image&id='.$r['id'].'" alt="">':'<div class="cover"></div>';$search=strtolower($r['artist'].' '.$r['title'].' '.$r['barcode']);$meta=($r['release_year']?:'—').' · '.playtime($r['duration_seconds']?(int)$r['duration_seconds']:null);$items.='<article class="record" data-search="'.e($search).'"><a href="?page=record&id='.$r['id'].'">'.$image.'</a><div class="record-body"><span class="tag">'.e($r['format']).'</span><h2>'.e($r['artist']).'</h2><p>'.e($r['title']).'</p><p>'.e((string)$meta).'</p></div></article>';}
layout('Collectie','<section class="hero"><h1>Je muziek, altijd bij de hand.</h1><p>Leg je cd’s en lp’s vast, inclusief hoes, tracklijst en barcode.</p><div class="actions"><a class="button" href="?page=add">+ Nieuwe uitgave</a><a class="button secondary" href="?page=scan">Barcode scannen</a></div></section><div class="toolbar"><strong>'.count($rows).' uitgave'.(count($rows)===1?'':'s').'</strong><input id="filter" type="search" placeholder="Zoek artiest, titel of barcode"></div>'.($items?'<section class="collection collection-list">'.$items.'</section>':'<section class="card empty">Je collectie is nog leeg. <a href="?page=add">Voeg je eerste uitgave toe.</a></section>'));
